package com.minhnb.finvera_be.alert;
import static org.mockito.Mockito.verifyNoInteractions;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import com.minhnb.finvera_be.alert.controller.*;import com.minhnb.finvera_be.alert.service.*;import com.minhnb.finvera_be.auth.config.OwnerSecurityConfiguration;import com.minhnb.finvera_be.auth.controller.OwnerAccessController;import com.minhnb.finvera_be.auth.service.OwnerSessionService;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.test.context.*;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
@WebMvcTest(controllers={OwnerAccessController.class,AlertController.class,NotificationController.class})@Import({OwnerSecurityConfiguration.class,OwnerSessionService.class})
class AlertSecurityTests{static final String OWNER="owner-"+UUID.randomUUID(),PASSWORD=UUID.randomUUID().toString(),HASH=new BCryptPasswordEncoder(4).encode(PASSWORD);@DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("finvera.security.owner.id",()->"00000000-0000-0000-0000-000000000001");r.add("finvera.security.owner.username",()->OWNER);r.add("finvera.security.owner.password-hash",()->HASH);}@Autowired MockMvc mvc;@MockitoBean AlertManagementService alerts;@MockitoBean NotificationService notifications;
 @Test void allReadRoutesRequireOwnerSession()throws Exception{String id=UUID.randomUUID().toString();for(String path:new String[]{"/api/v1/alerts","/api/v1/alerts/"+id,"/api/v1/alerts/"+id+"/evaluations","/api/v1/notifications","/api/v1/notifications/unread-count","/api/v1/notifications/"+id})mvc.perform(get(path)).andExpect(status().isUnauthorized());verifyNoInteractions(alerts,notifications);}
 @Test void mutationsRequireSessionAndCsrf()throws Exception{mvc.perform(post("/api/v1/alerts").with(csrf()).contentType("application/json").content("{}" )).andExpect(status().isUnauthorized());var login=mvc.perform(post("/api/v1/auth/session").with(csrf()).contentType("application/json").content("{\"username\":\""+OWNER+"\",\"password\":\""+PASSWORD+"\"}")).andExpect(status().isNoContent()).andReturn();var session=(org.springframework.mock.web.MockHttpSession)login.getRequest().getSession(false);mvc.perform(put("/api/v1/notifications/read-all").session(session)).andExpect(status().isForbidden());verifyNoInteractions(alerts,notifications);}
}
